#!/usr/bin/env python3
"""从固定 MDI 7.4.47 下载原路径并转成 VectorDrawable，不创作图标。仅本机维护。"""
from pathlib import Path
import urllib.request,xml.etree.ElementTree as ET,json,hashlib,ssl
TLS=ssl.create_default_context(cafile="/etc/ssl/cert.pem")
from concurrent.futures import ThreadPoolExecutor
ROOT=Path(__file__).resolve().parents[1]
ICONS={'live':'view-grid-outline','library':'movie-open-outline','settings':'tune','back':'chevron-left','chevron':'chevron-right','expand':'chevron-down','collapse':'chevron-up','storage':'harddisk','encode':'chip','record':'video-outline','vehicle':'car-outline','playback':'play-box-outline','diagnose':'pulse','about':'information-outline','refresh':'refresh','play':'play','pause':'pause','previous':'skip-previous','next':'skip-next','filter':'filter-variant','more':'dots-horizontal','lock':'lock-outline','left_turn':'arrow-left-bold','right_turn':'arrow-right-bold','steering':'steering','cruise':'car-cruise-control','low_beam':'car-light-dimmed','high_beam':'car-light-high','position':'car-parking-lights','fog':'car-light-fog','hold':'car-brake-hold','parking':'car-brake-parking','belt':'seatbelt','brake':'car-brake-alert','accelerator':'car-clutch'}
for key in ('low_beam','high_beam','position','brake','accelerator','cruise','steering','fog','hold','parking','live','library','settings','back','chevron','expand','collapse','storage','encode','record','vehicle','playback','diagnose','about','refresh','play','pause','previous','next','filter','more','lock'):
 ICONS.pop(key,None)
BASE='https://cdn.jsdelivr.net/npm/@mdi/svg@7.4.47/'
def convert(item):
 key,name=item;url=BASE+'svg/'+name+'.svg'
 raw=urllib.request.urlopen(url,timeout=30,context=TLS).read();svg=ET.fromstring(raw)
 paths=[e.attrib['d'] for e in svg.iter() if e.tag.endswith('path') and 'd' in e.attrib]
 assert paths and svg.attrib['viewBox']=='0 0 24 24',name
 body='\n'.join('    <path android:fillColor="#FFFFFFFF" android:pathData="'+p+'" />' for p in paths)
 target=ROOT/'galaxy/record/src/main/res/drawable'/('record_icon_'+key+'.xml')
 target.write_text('<!-- MDI 7.4.47 / '+name+'; Apache-2.0; generated by scripts/sync_autorecord_icons.py -->\n<vector xmlns:android="http://schemas.android.com/apk/res/android" android:width="24dp" android:height="24dp" android:viewportWidth="24" android:viewportHeight="24">\n'+body+'\n</vector>\n')
 return {'name':key,'source':url,'sourceSha256':hashlib.sha256(raw).hexdigest()}
with ThreadPoolExecutor(max_workers=6) as pool:manifest=list(pool.map(convert,ICONS.items()))
license=urllib.request.urlopen(BASE+'LICENSE',timeout=30,context=TLS).read()
(ROOT/'galaxy/record/src/main/assets/licenses/mdi-LICENSE.txt').write_bytes(license)
(ROOT/'galaxy/record/src/main/assets/licenses/mdi-icons.json').write_text(json.dumps({'version':'7.4.47','icons':manifest},indent=2)+'\n')
print('Imported',len(manifest),'original MDI icons and license')
